<?php
require_once __DIR__ . '/security.php'; require_once __DIR__ . '/db.php'; require_once __DIR__.'/control.php';
function current_user(): ?array { static $u=false;if($u!==false)return $u;$u=null;if(!empty($_SESSION['user_id'])){$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);$candidate=$s->fetch();if($candidate&&($candidate['status']??'active')==='active'){$ban=active_user_ban((int)$candidate['id']);if($ban){$_SESSION['account_ban_notice']=['reason'=>$ban['reason'],'expires_at'=>$ban['expires_at']];unset($_SESSION['user_id']);}else $u=$candidate;}}return $u; }
function require_login(): array { $u=current_user();if(!$u){header('Location: /login');exit;}return $u; }
function is_admin(): bool { return (current_user()['role']??'user')==='admin'; }
function record_auth_activity(string $event,?int $userId=null,?string $email=null): void {try{$ip=hash('sha256',client_ip().'|'.DB_NAME);$ua=substr($_SERVER['HTTP_USER_AGENT']??'',0,500);$q=db()->prepare('INSERT INTO auth_activity(user_id,email,event,ip_hash,user_agent,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP())');$q->execute([$userId,$email?strtolower($email):null,substr($event,0,30),$ip,$ua]);}catch(Throwable $ignored){}}
